#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Install and run ROM 9.0.12i4a Player Progression legacy audit."""
from __future__ import annotations

import base64
import py_compile
import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path

PATCH_ID = "9.0.12i4a"
TARGET_NAME = "smoke_test_player_progression_legacy_audit.py"
TOOL_SOURCE = base64.b64decode("").decode("utf-8")


def fail(message: str) -> None:
    print(f"ERROR: {message}")
    raise SystemExit(1)


def find_root() -> Path:
    script = Path(__file__).resolve()
    for candidate in (script.parent.parent, Path.cwd(), Path.cwd().parent):
        candidate = candidate.resolve()
        if (candidate / "db.py").is_file() and (candidate / "systems" / "player_system.py").is_file():
            return candidate
    fail("ROM project root was not found.")
    raise AssertionError("unreachable")


def main() -> None:
    root = find_root()
    target = root / "tools" / TARGET_NAME
    backup = None

    if target.exists() and target.read_text(encoding="utf-8-sig") != TOOL_SOURCE:
        backup_dir = root / "backup"
        backup_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup = backup_dir / f"tools_{TARGET_NAME}_{PATCH_ID}_{stamp}.bak"
        shutil.copy2(target, backup)

    target.write_text(TOOL_SOURCE, encoding="utf-8")

    try:
        py_compile.compile(str(target), doraise=True)
        result = subprocess.run([sys.executable, str(target)], cwd=root, check=False)
        if result.returncode != 0:
            raise RuntimeError(f"audit exit code {result.returncode}")
    except Exception as exc:
        if backup is not None and backup.exists():
            shutil.copy2(backup, target)
        elif target.exists():
            target.unlink()
        fail(f"Audit failed; installation rolled back: {exc}")

    print(f"Patch {PATCH_ID} applied successfully.")
    print(f"Created: tools/{TARGET_NAME}")
    print("Created: DB_CLEANUP_9_0_12I4A_PLAYER_PROGRESSION_AUDIT.md")
    print("Gameplay code, database rows, and legacy refs were not changed.")
    print("Backups:")
    print(f"  {backup.relative_to(root) if backup else 'not required - new audit file'}")
    print("Run again:")
    print(f"  python ./tools/{TARGET_NAME}")
    print("Readiness:")
    print("  python ./tools/db_cleanup_readiness.py")


if __name__ == "__main__":
    main()
